"""The stable CLI argument surface; no runtime or business imports."""
import argparse


def build_parser(description):
    parser = argparse.ArgumentParser(description=description)
    sub = parser.add_subparsers(dest='command', required=True)
    p = sub.add_parser('trace')
    p.add_argument('directory')
    p.add_argument('--task')
    p.add_argument('--json', action='store_true')
    p = sub.add_parser('create')
    p.add_argument('--repo', required=True)
    p.add_argument('--plan', required=True)
    p = sub.add_parser('workflow-create')
    p.add_argument('--repo', required=True)
    p.add_argument('--plan', required=True)
    p.add_argument('--origin-thread')
    p.add_argument('--origin-ref')
    p.add_argument('--auto-recover', action='store_true')
    p.add_argument('--recovery-source')
    p = sub.add_parser('workflow-validate')
    p.add_argument('plan')
    p = sub.add_parser('workflow-close')
    p.add_argument('directory')
    p.add_argument('--evidence', required=True)
    p.add_argument('--source', required=True)
    p = sub.add_parser('watch')
    p.add_argument('directory')
    p.add_argument('--source', required=True)
    p = sub.add_parser('failure-alerts')
    p.add_argument('--source', required=True)
    p = sub.add_parser('acknowledge')
    p.add_argument('directory')
    p.add_argument('--criterion', required=True)
    p.add_argument('--evidence', required=True)
    p.add_argument('--note', required=True)
    p.add_argument('--actor-file')
    for name in ('start', 'resume', 'run', '_worker', 'status', 'stop'):
        p = sub.add_parser(name)
        p.add_argument('directory')
        if name in ('start', 'resume', 'run', '_worker'):
            p.add_argument('--retry-failed', action='store_true')
        if name == 'resume':
            p.add_argument('--accepted-answer')
    p = sub.add_parser('validate')
    p.add_argument('plan')
    p = sub.add_parser('permission-check')
    p.add_argument('--repo', required=True)
    p.add_argument('--plan', required=True)
    p = sub.add_parser('host-checks')
    p.add_argument('directory')
    p.add_argument('--source', required=True)
    p = sub.add_parser('host-recheck')
    p.add_argument('directory')
    p.add_argument('--task', required=True)
    p.add_argument('--source', required=True)
    p = sub.add_parser('budget-estimate')
    p.add_argument('--estimate', required=True)
    p = sub.add_parser('budget-policy')
    p.add_argument('action', choices=['status', 'set'])
    p.add_argument('--mode', choices=['advisory', 'enforced'])
    p.add_argument('--source')
    p.add_argument('--request')
    p = sub.add_parser('budget-configure')
    p.add_argument('directory')
    p.add_argument('--estimate', required=True)
    p.add_argument('--source', required=True)
    p.add_argument('--request', required=True)
    p.add_argument('--hard-limit-seconds', type=int)
    p.add_argument('--accepted-answer')
    p = sub.add_parser('budget-reforecast')
    p.add_argument('directory')
    p.add_argument('--estimate', required=True)
    p.add_argument('--source', required=True)
    p.add_argument('--request', required=True)
    p = sub.add_parser('budget-charge')
    p.add_argument('directory')
    p.add_argument('--seconds', type=float, required=True)
    p.add_argument('--source', required=True)
    p.add_argument('--evidence', required=True)
    p.add_argument('--request', required=True)
    p = sub.add_parser('budget-run')
    p.add_argument('directory')
    p.add_argument('--source', required=True)
    p.add_argument('argv', nargs=argparse.REMAINDER)
    p = sub.add_parser('list')
    p.add_argument('--repo', required=True)
    p = sub.add_parser('supervise')
    p.add_argument('directory')
    p.add_argument('--source', required=True)
    p.add_argument('--max-requests', type=int, default=3)
    p.add_argument('--same-blocker-limit', type=int, default=2)
    p.add_argument('--response-seconds', type=int, default=1800)
    p.add_argument('--window-seconds', type=int, default=14400)
    for name in ('unsupervise', '_supervisor'):
        p = sub.add_parser(name)
        p.add_argument('directory')
    p = sub.add_parser('takeover')
    p.add_argument('directory')
    p.add_argument('--request', required=True)
    p.add_argument('--state', choices=['working', 'repaired', 'needs_input', 'blocked'], required=True)
    p.add_argument('--note', required=True)
    p.add_argument('--evidence')
    p.add_argument('--recommendation', default='')
    p = sub.add_parser('takeover-status')
    p.add_argument('directory')
    p.add_argument('--request', required=True)
    p = sub.add_parser('hub')
    p.add_argument('--thread')
    p.add_argument('--session-ref')
    p.add_argument('--source')
    p.add_argument('--actor-file')
    p = sub.add_parser('local-session-create')
    p.add_argument('--project', required=True)
    p.add_argument('--role', choices=['hub', 'origin'], required=True)
    p.add_argument('--source', required=True)
    p.add_argument('--credential-file', required=True)
    p.add_argument('--user-credential-file')
    p = sub.add_parser('local-session-grant')
    p.add_argument('--credential-file', required=True)
    p.add_argument('--workflow', required=True)
    p.add_argument('--output', required=True)
    p.add_argument('--source', required=True)
    p = sub.add_parser('session-register')
    p.add_argument('--kind', required=True)
    p.add_argument('--identity', required=True)
    p.add_argument('--project', required=True)
    p.add_argument('--source', required=True)
    p = sub.add_parser('ask')
    p.add_argument('directory')
    p.add_argument('--question', required=True)
    p.add_argument('--recommendation', default='')
    p.add_argument('--context', default='')
    p.add_argument('--request')
    p.add_argument('--actor-file')
    p = sub.add_parser('inbox')
    p.add_argument('--actor-file')
    p = sub.add_parser('read-question', aliases=['read'])
    p.add_argument('identifier')
    p.add_argument('--actor-file')
    p.add_argument('--presented-source')
    p = sub.add_parser('answer', aliases=['respond'])
    p.add_argument('identifier')
    p.add_argument('--answer', required=True)
    p.add_argument('--source', required=True)
    p.add_argument('--actor-file')
    p = sub.add_parser('accept-answer')
    p.add_argument('identifier')
    p.add_argument('--budget-stop-evidence')
    p.add_argument('--actor-file')
    p = sub.add_parser('continue-task')
    p.add_argument('directory')
    p.add_argument('--accepted-answer', required=True)
    p.add_argument('--actor-file', required=True)
    p = sub.add_parser('control')
    p.add_argument('action', choices=['start', 'stop', 'status', 'tick'])
    p.add_argument('--source')
    p.add_argument('--reminder-seconds', type=int, default=900)
    p.add_argument('--max-reminders', type=int, default=3)
    p = sub.add_parser('notification-policy')
    p.add_argument('action', choices=['status', 'set', 'mute', 'unmute'])
    p.add_argument('--mode', choices=['all', 'user_input_only'])
    p.add_argument('--source')
    p.add_argument('--repo')
    p.add_argument('--completion', choices=['once', 'silent'])
    p = sub.add_parser('followups')
    p.add_argument('--all', action='store_true')
    p = sub.add_parser('presented')
    p.add_argument('identifier')
    p.add_argument('--source', required=True)
    p = sub.add_parser('followup-link')
    p.add_argument('identifier')
    p.add_argument('--workflow', required=True)
    p.add_argument('--note', required=True)
    p.add_argument('--evidence', required=True)
    p = sub.add_parser('workflow-link')
    p.add_argument('predecessor')
    p.add_argument('--successor', required=True)
    p.add_argument('--evidence', required=True)
    p.add_argument('--source', required=True)
    p = sub.add_parser('operational-disposition')
    p.add_argument('identifier')
    p.add_argument('--category', choices=['handler_assignment', 'permission', 'decision', 'missing_information', 'manual_acceptance'], required=True)
    p.add_argument('--blocker', required=True)
    p.add_argument('--tried', required=True)
    p.add_argument('--evidence', action='append', required=True)
    p.add_argument('--recommendation', required=True)
    p.add_argument('--source', required=True)
    sub.add_parser('_controller')
    sub.add_parser('agent-doctor')
    p = sub.add_parser('delegate')
    p.add_argument('--repo', required=True)
    p.add_argument('--plan', required=True)
    p.add_argument('--name', required=True)
    p.add_argument('--source', required=True)
    p.add_argument('--request-id')
    p.add_argument('--timeout', type=int, default=600)
    p.add_argument('--session-kind', default='codex')
    for name in ('delegation-status', 'delegation-accept', '_dispatcher'):
        p = sub.add_parser(name)
        p.add_argument('directory')
    return parser
